-- =====================================================================
-- V1.2.0 : T_BRANCH (조합/본지점 정보) + T_CORNER (코너 마스터)
-- 레거시 새마을금고(datm) 스키마를 Oracle 19C 로 이식.
--   - 영업점 코드→명칭 매핑(T_BRANCH)에 필요
--   - 코너 마스터(T_CORNER) : 코너변경/기기설치 위치 표시에 필요
-- 원본 oracle19c_ddl.sql 의 MySQL 잔재(varchar(...) COMMENT ...) 를 Oracle 문법으로 정정.
-- 시드 데이터는 datm.* → ATMS 스키마(T_*) 로 변환.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1) T_BRANCH (T_조합정보)
-- ---------------------------------------------------------------------
CREATE TABLE T_BRANCH (
    TERM_GROUP_ID    CHAR(5)        NOT NULL,   -- 영업점코드
    BRANCH_CD        VARCHAR2(5)    NOT NULL,   -- 본지점코드
    BRANCH_NAME      VARCHAR2(200)  NOT NULL,   -- 본지점명
    BRANCH_TYPE_CD   CHAR(1),                   -- 본지점구분
    ZIPCODE          CHAR(6),                   -- 우편코드
    ADDRESS          VARCHAR2(255),             -- 주소
    DETAIL_ADDRESS   VARCHAR2(100),             -- 상세주소
    PHONE_NO         VARCHAR2(50),              -- 전화번호
    FAX_NO           VARCHAR2(30),              -- 팩스번호
    PARTNER_CD       CHAR(2),                   -- 작업자코드
    BLNG_SOTY_CD     CHAR(3),                   -- 건물번호
    SOTY_NM          CHAR(20),                  -- 지역명
    TERM_GROUP_NAME  CHAR(40),                  -- 영업점명
    ADDR_SEQ         VARCHAR2(10),              -- 주소일련번호
    CONSTRAINT PK_T_BRANCH PRIMARY KEY (TERM_GROUP_ID, BRANCH_CD, BRANCH_NAME)
);

COMMENT ON TABLE  T_BRANCH                 IS 'T_조합정보';
COMMENT ON COLUMN T_BRANCH.TERM_GROUP_ID  IS '영업점코드';
COMMENT ON COLUMN T_BRANCH.BRANCH_CD      IS '본지점코드';
COMMENT ON COLUMN T_BRANCH.BRANCH_NAME    IS '본지점명';
COMMENT ON COLUMN T_BRANCH.BRANCH_TYPE_CD IS '본지점구분';
COMMENT ON COLUMN T_BRANCH.ZIPCODE        IS '우편코드';
COMMENT ON COLUMN T_BRANCH.ADDRESS        IS '주소';
COMMENT ON COLUMN T_BRANCH.DETAIL_ADDRESS IS '상세주소';
COMMENT ON COLUMN T_BRANCH.PHONE_NO       IS '전화번호';
COMMENT ON COLUMN T_BRANCH.FAX_NO         IS '팩스번호';
COMMENT ON COLUMN T_BRANCH.PARTNER_CD     IS '작업자코드';
COMMENT ON COLUMN T_BRANCH.BLNG_SOTY_CD   IS '건물번호';
COMMENT ON COLUMN T_BRANCH.SOTY_NM        IS '지역명';
COMMENT ON COLUMN T_BRANCH.TERM_GROUP_NAME IS '영업점명';
COMMENT ON COLUMN T_BRANCH.ADDR_SEQ       IS '주소일련번호';

-- ---------------------------------------------------------------------
-- 2) T_CORNER (T_코너마스터)
--    원본의 AREA1~3_CD MySQL 인라인 COMMENT 를 Oracle 문법으로 분리.
-- ---------------------------------------------------------------------
CREATE TABLE T_CORNER (
    TERM_GROUP_ID        CHAR(5)        NOT NULL,   -- 영업점코드
    CORNER_CD            CHAR(3)        NOT NULL,   -- 코너코드
    CORNER_NAME          VARCHAR2(200),             -- 코너명
    CORNER_TYPE_CD       CHAR(1),                   -- 코너구분코드
    OPERATION_TYPE_CD    CHAR(1),                   -- 운영구분코드
    LOCATION_TYPE_CD     CHAR(2),                   -- 설치장소구분코드
    SERVICE_START_TIME   CHAR(4),                   -- 운영시작시간
    SERVICE_END_TIME     CHAR(4),                   -- 운영종료시간
    SERVICE_WEEKDAY      CHAR(7),                   -- 운영요일
    BOOTH_TYPE_CD        CHAR(2),                   -- 부스타입
    BOOTH_COUNT          NUMBER(19),                -- 부스갯수
    MANAGE_TYPE_CD       CHAR(1),                   -- 관리구분코드
    OUTSRC_CO_CD         CHAR(2),                   -- 코너용역업체코드
    GUARD_CO_CD          CHAR(2),                   -- 경비업체코드
    GUARD_BR_CD          CHAR(2),                   -- 경비지사코드
    GUARD_CRTNO          VARCHAR2(20),              -- 경비계약번호
    GUARD_STATUS         CHAR(1)        DEFAULT '0',-- 경비상태
    CORNER_SAFE_USE_FLAG CHAR(1)        DEFAULT '9',-- 코너금고사용여부
    CORNER_STATUS        CHAR(1),                   -- 코너상태
    OPEN_DATE            CHAR(8),                   -- 개설일자
    CLOSE_DATE           CHAR(8),                   -- 폐쇄일자
    TEMP_CLS_START_DATE  CHAR(8),                   -- 임시폐쇄시작일자
    TEMP_CLS_END_DATE    CHAR(8),                   -- 임시폐쇄종료일자
    TEMP_CLS_REASON      VARCHAR2(100),             -- 임시폐쇄사유
    PHONE_NO             VARCHAR2(50),              -- 전화번호
    ZIPCODE              CHAR(6),                   -- 우편번호
    AREA1_CD             VARCHAR2(20),              -- 지역코드1
    AREA2_CD             VARCHAR2(20),              -- 시군구
    AREA3_CD             VARCHAR2(100),             -- 읍면동
    DETAIL_ADDRESS       VARCHAR2(100),             -- 상세주소
    ADDRESS              VARCHAR2(255),             -- 주소
    LOCATION             VARCHAR2(200),             -- 위치
    LEASE_DEPOSIT        NUMBER(19),                -- 임대보증금
    LEASE_VALUE          NUMBER(19),                -- 임대료
    CHECK_DEP_FLAG       CHAR(1)        DEFAULT '0',-- 수표입금여부
    CHECK_WIT_FLAG       CHAR(1)        DEFAULT '0',-- 수표출금여부
    LAT                  VARCHAR2(15),              -- 위도
    LNG                  VARCHAR2(15),              -- 경도
    BASE_CHARGE          NUMBER(19),                -- 기본수수료
    ATM_ADD_CHARGE       NUMBER(19),                -- ATM추가수수료
    TIME_ADD_CHARGE      NUMBER(19),                -- 시간외추가수수료
    CHECK_CHARGE         NUMBER(19),                -- 수표수수료
    SERVICE_SPEC         VARCHAR2(500),             -- 서비스명세
    ENTER_DATE           CHAR(8),                   -- 등록일자
    ENTER_TIME           CHAR(6),                   -- 등록시각
    ENTER_USER_ID        VARCHAR2(10),              -- 등록자ID
    CCTV_SET_FLAG        CHAR(1),                   -- CCTV설치여부
    GUARD_EQUIP_CHARGE   NUMBER(19),                -- 경비장비수수료
    DVR_IP               VARCHAR2(15),              -- DVR IP
    ENG_SIDO             VARCHAR2(200),             -- 영문시도
    ENG_ADM_GG           VARCHAR2(200),             -- 영문시군구
    ENG_ADDR             VARCHAR2(200),             -- 영문주소
    BRANCH_CD            VARCHAR2(5),               -- 본지점코드
    PARTNER_CD           CHAR(2),                   -- 작업자코드
    MAINT_TYPE_CD        CHAR(1),                   -- 유지보수구분코드
    PARTNER_NAME         VARCHAR2(50),              -- 작업자명
    GUARD_CO_NAME        VARCHAR2(50),              -- 경비업체명
    HOLIDAY_START_TIME   CHAR(4),                   -- 휴일운영시작시간
    HOLIDAY_END_TIME     CHAR(4),                   -- 휴일운영종료시간
    HOLIDAY_SERVICE      CHAR(7),                   -- 휴일운영여부
    CONSTRAINT PK_T_CORNER PRIMARY KEY (TERM_GROUP_ID, CORNER_CD)
);

COMMENT ON TABLE  T_CORNER                    IS 'T_코너마스터';
COMMENT ON COLUMN T_CORNER.TERM_GROUP_ID      IS '영업점코드';
COMMENT ON COLUMN T_CORNER.CORNER_CD          IS '코너코드';
COMMENT ON COLUMN T_CORNER.CORNER_NAME        IS '코너명';
COMMENT ON COLUMN T_CORNER.CORNER_TYPE_CD     IS '코너구분코드';
COMMENT ON COLUMN T_CORNER.OPERATION_TYPE_CD  IS '운영구분코드';
COMMENT ON COLUMN T_CORNER.LOCATION_TYPE_CD   IS '설치장소구분코드';
COMMENT ON COLUMN T_CORNER.CORNER_STATUS      IS '코너상태';
COMMENT ON COLUMN T_CORNER.OPEN_DATE          IS '개설일자';
COMMENT ON COLUMN T_CORNER.BRANCH_CD          IS '본지점코드';

CREATE INDEX IX_T_CORNER_BRANCH ON T_CORNER (TERM_GROUP_ID, BRANCH_CD);

